import numpy as np


def ring_share(S, radii, band):
    S = np.asarray(S, dtype=float)
    r = np.sqrt((S ** 2).sum(axis=1))
    gaps = np.abs(r[:, None] - np.asarray(radii, dtype=float)[None, :])
    return float(np.mean(gaps[:, 0] < band))
